mapper.select:
select t.pk_id, t.rd_project_id, t.budget_code, t.budget_name, t.contract_code, t.contract_start_date, t.contract_end_date, t.maintenance_start_date, t.maintenance_end_date, t.contract_amount, t.payment_sche, t.project_allocation_ratio, t.create_by, t.create_date, t.update_by, t.update_date, t.contract_name, t.type, t.budget_amount, t.supplier, t.approved_date, t.is_research_project, t.tech_inno_point, t.contract_tax_points, t.supplier_name, t.expense_type, t.reimbursement_item, t.account_subject, t.is_invoice, t.remark_lan, t.payment_scheduling, t.invoice_Type, t.contract_Start_Date_Flag, t.contract_end_Date_Flag, (select listagg(p.project_name, ',') WITHIN group(order by r.create_date) from ppm.rd_project_contract_relation r inner join ppm.rd_project p on r.rd_project_id = p.pk_id where r.rd_project_contract_id = t.pk_id) project_name, t.software_manpower, t.assist_manpower, t.risk_management_manpower from rd_project_contract t where t.DELETED='0' and t.contract_code like '%'||#{contractCode}||'%'
and exists(select 1 from ppm.rd_project p inner join ppm.rd_project_contract_relation r on r.rd_project_id=p.pk_id where r.rd_project_contract_id=t.pk_id and p.project_name like '%'||#{projectName}||'%')
and t.contract_name like '%'||#{contractName}||'%' and t.budget_code like '%'||#{budgetCode}||'%' and t.budget_name like '%'||#{budgetName}||'%'
order by t.${prop} ${order}
order by to_number(t.${prop}) ${order}
order by ${prop} ${order}
order by t.budget_code desc
